// Loads the JSON emitted by scripts/build-content.mjs.
//
// The Markdown in career-roadmaps/ is the single source of truth. These JSON
// files are build artifacts, regenerated by `npm run build:content` and
// git-ignored. See docs/CONTENT-SCHEMA.md and docs/DECISIONS.md D-006.

import it from "./generated/it.json";
import cyber from "./generated/cyber.json";

export const tracks = [
  {
    id: "it",
    label: "IT Roadmap",
    short: "IT",
    note: "First goal — remote entry-level IT in 3–6 months.",
    phases: it.phases,
  },
  {
    id: "cyber",
    label: "Cybersecurity",
    short: "Cyber",
    note: "Second goal — entry-level cyber in 6–18 months.",
    phases: cyber.phases,
  },
];

export function findTrack(id) {
  return tracks.find((t) => t.id === id) || null;
}

export function allTasks(track) {
  return track.phases.flatMap((p) => p.checklist);
}